sources.RibbonCanvas.ets:
@Component
export struct RibbonCanvas {
  @Builder
  renderStrip() {
    Row() {
      Text('north')
      Text('south')
    }
    .height(72)
    .alignItems(VerticalAlign.Center)
  }
  build() {
    Column() {
      this.renderStrip()
    }
  }
}

